	ea = -112 + ctx.r1.u32;
	REX_STORE_U32(ea, ctx.r1.u32);
	ctx.r1.u32 = ea;
	// addi r31,r3,-500
	r31.s64 = ctx.r3.s64 + -500;
	// mr r30,r4
	r30.u64 = ctx.r4.u64;
	// addi r3,r31,240
	ctx.r3.s64 = r31.s64 + 240;
